WITH filtered AS (SELECT id, customer_id, device, SUBSTRING(country, 1, 4) AS country_prefix FROM sessions WHERE browser IS NOT NULL AND customer_id IN (7, 10)), with_latest AS (SELECT s.*, x.duration_sec, x.web_event_event_type FROM filtered s LEFT JOIN LATERAL (SELECT c.duration_sec, c.event_type AS web_event_event_type FROM web_events c WHERE c.session_id = s.id ORDER BY c.event_time DESC, c.id DESC LIMIT 1) x ON TRUE), scored AS (SELECT id, device, country_prefix, duration_sec, AVG(duration_sec) OVER w_recent AS duration_sec_avg_3, ROW_NUMBER() OVER w_part AS event_seq, LAST_VALUE(web_event_event_type, TRUE) OVER (PARTITION BY web_event_event_type ORDER BY duration_sec ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_web_event_event_type FROM with_latest WINDOW w_recent AS (PARTITION BY device ORDER BY duration_sec ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY customer_id ORDER BY duration_sec DESC, id ASC)), kept AS (SELECT s.* FROM scored s WHERE NOT EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.event_time < '2024-08-08')), scored_sessions AS (SELECT *, AVG(duration_sec_avg_3) OVER (PARTITION BY device ORDER BY duration_sec_avg_3 ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_duration_sec_avg_3, MAX(duration_sec_avg_3) OVER (PARTITION BY device ORDER BY duration_sec_avg_3 ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_duration_sec_avg_3, COUNT(duration_sec_avg_3) OVER (PARTITION BY device ORDER BY duration_sec_avg_3 ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_duration_sec_avg_3 FROM kept WHERE device <> 'desktop'), totals AS (SELECT device, COUNT(*) AS event_count, COUNT_IF(device = 'mobile') AS mobile_events, SUM(running_count_duration_sec_avg_3) FILTER (WHERE device = 'mobile') AS mobile_total_running_count_duration_sec_avg_3, COUNT(*) AS cnt, SIZE(COLLECT_SET(device)) AS num_devices FROM scored_sessions GROUP BY 1 HAVING COUNT_IF(device = 'mobile') >= 1) SELECT device, event_count, mobile_events, mobile_total_running_count_duration_sec_avg_3, CASE WHEN device RLIKE '^(tablet|mobile)$' THEN 'OTHER_ZONE' WHEN device RLIKE '^(desktop)$' THEN 'PRIORITY' ELSE 'EXTENDED' END AS device_zone FROM totals;
